style.css:
@-moz-document domain("pinterest.com") {
/* Main page, feed, and top bar wrappers */
  html, body, #__PWS_ROOT__,
  [data-test-id="home-feed"],
  [data-test-id="header"],
  [data-test-id="header-background"],
  div[style*="background-color: rgb(255, 255, 255)"],
  div[style*="background-color: white"] {
    background-color: #121212 !important;
  }

  /* Board tabs strip ("All", "Real", "childhood", etc.) */
  [data-test-id="board-header"],
  [role="tablist"],
  nav {
    background-color: #181818 !important;
  }

  /* Search bar container, input, and profile pill */
  [data-test-id="search-box"],
  [data-test-id="search-box-container"],
  [data-test-id="search-input"],
  input[type="text"],
  input[type="search"],
  form[role="search"] > div {
    background-color: #242424 !important;
    color: #f5f5f5 !important;
    border-color: #333333 !important;
  }

  /* Floating question mark button in the bottom right */
  [data-test-id="help-button"],
  button[aria-label*="More"],
  div[role="button"] {
    background-color: #222222 !important;
  }

  /* Darken top header icons (search, notifications, messages) */
  header svg, nav svg {
    fill: #e0e0e0 !important;
    color: #e0e0e0 !important;
  }

  /* General text color */
  p, span, h1, h2, h3, a, div {
    color: #e0e0e0 !important;
  }
}
